function numberOfWays(n, x, y) {
  const MOD = 1000000007;
  const bands = Math.min(n, x);
  const stirling = new Array(bands + 1).fill(0);
  stirling[0] = 1;
  for (let i = 1; i <= n; i++) {
    for (let k = Math.min(i, bands); k >= 1; k--) {
      stirling[k] = (stirling[k - 1] + k * stirling[k]) % MOD;
    }
    stirling[0] = 0;
  }
  let total = 0;
  let factor = 1;
  for (let k = 1; k <= bands; k++) {
    factor = factor * (x - k + 1) % MOD * y % MOD;
    const ways = Number(BigInt(stirling[k]) * BigInt(factor) % BigInt(MOD));
    total = (total + ways) % MOD;
  }
  return total;
}

