function numberOfWays(n, x, y) {
  // Seat performers one at a time. count[j] = ways so far that use exactly j stages, every band already scored.
  // Products stay below 2^51 (a residue times at most 1000 * 1000), so plain numbers are exact.
  const MOD = 1000000007;
  let count = [1];
  for (let performer = 0; performer < n; performer++) {
    const next = new Array(count.length + 1).fill(0);
    for (let j = 0; j < count.length; j++) {
      next[j] = (next[j] + count[j] * j) % MOD;
      if (j < x) next[j + 1] = (next[j + 1] + count[j] * ((x - j) * y)) % MOD;
    }
    count = next;
  }
  let sum = 0;
  for (const value of count) sum = (sum + value) % MOD;
  return sum;
}

