function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') return [pick(800, 1000), pick(800, 1000), pick(1, 1000)];
  const n = rand() < 0.5 ? pick(1, 6) : pick(1, 60);
  const x = rand() < 0.5 ? pick(1, 6) : pick(1, 60);
  const y = rand() < 0.5 ? pick(1, 5) : pick(1, 1000);
  return [n, x, y];
}
